@startuml

class User {}

class Doctor extends User {
  + CreateSchedule(office: Office, date: Date, startTime: Time, endTime: Time)
}

class Patient extends User {
  + CreateAppointment(doctor: Doctor, schedule: Schedule)
}

class Hospital {}

class Office {}

class Schedule {}

class Appointment {}

class BloodTest extends Appointment {}

class Consultation extends Appointment {}

class Surgery extends Appointment {}

Hospital "1" -- "*" Office
Doctor "1..*" -- "*" Office : practices in
Doctor "1" -- "*" Schedule : creates
Office "1" -- "*" Schedule
Patient "1" -- "*" Appointment : books
Schedule "1" -- "*" Appointment : has
Appointment "1" -- "1" Doctor : for
Appointment "1" -- "1" Schedule : at

@enduml

